// KNN Directional Vote 7x20 3D
// KNN nearest-neighbour voting on next-bar direction with vote margin + disagreement channels

kIn = input(7, "K Neighbors", 1, 15, 1)
featWin = input(20, "Feature Window", 5, 30, 1)
searchHist = input(250, "Search History", 50, 500, 10)
crispThresh = input(0.71, "Crisp Margin Threshold", 0.5, 1.0, 0.01)
maxDis = input(0.6, "Max Disagreement", 0.1, 2.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Per-bar feature vector F[t]: 20 close-to-close percent changes ───
f0 = (close / close[1] - 1) * 100
f1 = (close[1] / close[2] - 1) * 100
f2 = (close[2] / close[3] - 1) * 100
f3 = (close[3] / close[4] - 1) * 100
f4 = (close[4] / close[5] - 1) * 100
f5 = (close[5] / close[6] - 1) * 100
f6 = (close[6] / close[7] - 1) * 100
f7 = (close[7] / close[8] - 1) * 100
f8 = (close[8] / close[9] - 1) * 100
f9 = (close[9] / close[10] - 1) * 100
f10 = (close[10] / close[11] - 1) * 100
f11 = (close[11] / close[12] - 1) * 100
f12 = (close[12] / close[13] - 1) * 100
f13 = (close[13] / close[14] - 1) * 100
f14 = (close[14] / close[15] - 1) * 100
f15 = (close[15] / close[16] - 1) * 100
f16 = (close[16] / close[17] - 1) * 100
f17 = (close[17] / close[18] - 1) * 100
f18 = (close[18] / close[19] - 1) * 100
f19 = (close[19] / close[20] - 1) * 100

// ─── Normalize by own max absolute value ───
maxA0 = abs(f0)
maxA1 = abs(f1)
if abs(f1) > maxA0 { maxA1 := abs(f1) }
if abs(f2) > maxA1 { maxA1 := abs(f2) }
if abs(f3) > maxA1 { maxA1 := abs(f3) }
if abs(f4) > maxA1 { maxA1 := abs(f4) }
if abs(f5) > maxA1 { maxA1 := abs(f5) }
if abs(f6) > maxA1 { maxA1 := abs(f6) }
if abs(f7) > maxA1 { maxA1 := abs(f7) }
if abs(f8) > maxA1 { maxA1 := abs(f8) }
if abs(f9) > maxA1 { maxA1 := abs(f9) }
if abs(f10) > maxA1 { maxA1 := abs(f10) }
if abs(f11) > maxA1 { maxA1 := abs(f11) }
if abs(f12) > maxA1 { maxA1 := abs(f12) }
if abs(f13) > maxA1 { maxA1 := abs(f13) }
if abs(f14) > maxA1 { maxA1 := abs(f14) }
if abs(f15) > maxA1 { maxA1 := abs(f15) }
if abs(f16) > maxA1 { maxA1 := abs(f16) }
if abs(f17) > maxA1 { maxA1 := abs(f17) }
if abs(f18) > maxA1 { maxA1 := abs(f18) }
if abs(f19) > maxA1 { maxA1 := abs(f19) }
maxAbs = maxA1
if maxAbs < 0.000000001 { maxAbs := 0.000000001 }

n0 = f0 / maxAbs
n1 = f1 / maxAbs
n2 = f2 / maxAbs
n3 = f3 / maxAbs
n4 = f4 / maxAbs
n5 = f5 / maxAbs
n6 = f6 / maxAbs
n7 = f7 / maxAbs
n8 = f8 / maxAbs
n9 = f9 / maxAbs
n10 = f10 / maxAbs
n11 = f11 / maxAbs
n12 = f12 / maxAbs
n13 = f13 / maxAbs
n14 = f14 / maxAbs
n15 = f15 / maxAbs
n16 = f16 / maxAbs
n17 = f17 / maxAbs
n18 = f18 / maxAbs
n19 = f19 / maxAbs
curArr = [n0, n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12, n13, n14, n15, n16, n17, n18, n19]

// ─── Persistent close history for neighbour search ───
varip closeHist = array(0)
array.push(closeHist, close)
numBars = array.size(closeHist)

// ─── KNN distance search over last searchHist bars ───
var mVote = 0.0
var sDis = 1.0
warmup = bar_index >= featWin + 2 and numBars >= featWin + 3

if warmup {
    bestD0 = 999999.0
    bestD1 = 999999.0
    bestD2 = 999999.0
    bestD3 = 999999.0
    bestD4 = 999999.0
    bestD5 = 999999.0
    bestD6 = 999999.0
    bestL0 = 0
    bestL1 = 0
    bestL2 = 0
    bestL3 = 0
    bestL4 = 0
    bestL5 = 0
    bestL6 = 0
    bestArr = [bestD0, bestD1, bestD2, bestD3, bestD4, bestD5, bestD6]
    labArr = [bestL0, bestL1, bestL2, bestL3, bestL4, bestL5, bestL6]

    searchStart = numBars - 1 - searchHist
    if searchStart < featWin + 1 { searchStart := featWin + 1 }
    if searchStart < 0 { searchStart := 0 }

    j = searchStart
    while j < numBars - 1 {
        c0 = closeHist[j]
        c1 = closeHist[j - 1]
        c2 = closeHist[j - 2]
        c3 = closeHist[j - 3]
        c4 = closeHist[j - 4]
        c5 = closeHist[j - 5]
        c6 = closeHist[j - 6]
        c7 = closeHist[j - 7]
        c8 = closeHist[j - 8]
        c9 = closeHist[j - 9]
        c10 = closeHist[j - 10]
        c11 = closeHist[j - 11]
        c12 = closeHist[j - 12]
        c13 = closeHist[j - 13]
        c14 = closeHist[j - 14]
        c15 = closeHist[j - 15]
        c16 = closeHist[j - 16]
        c17 = closeHist[j - 17]
        c18 = closeHist[j - 18]
        c19 = closeHist[j - 19]
        c20 = closeHist[j - 20]
        p0 = (c0 / c1 - 1) * 100
        p1 = (c1 / c2 - 1) * 100
        p2 = (c2 / c3 - 1) * 100
        p3 = (c3 / c4 - 1) * 100
        p4 = (c4 / c5 - 1) * 100
        p5 = (c5 / c6 - 1) * 100
        p6 = (c6 / c7 - 1) * 100
        p7 = (c7 / c8 - 1) * 100
        p8 = (c8 / c9 - 1) * 100
        p9 = (c9 / c10 - 1) * 100
        p10 = (c10 / c11 - 1) * 100
        p11 = (c11 / c12 - 1) * 100
        p12 = (c12 / c13 - 1) * 100
        p13 = (c13 / c14 - 1) * 100
        p14 = (c14 / c15 - 1) * 100
        p15 = (c15 / c16 - 1) * 100
        p16 = (c16 / c17 - 1) * 100
        p17 = (c17 / c18 - 1) * 100
        p18 = (c18 / c19 - 1) * 100
        p19 = (c19 / c20 - 1) * 100
        pMax = abs(p0)
        if abs(p1) > pMax { pMax := abs(p1) }
        if abs(p2) > pMax { pMax := abs(p2) }
        if abs(p3) > pMax { pMax := abs(p3) }
        if abs(p4) > pMax { pMax := abs(p4) }
        if abs(p5) > pMax { pMax := abs(p5) }
        if abs(p6) > pMax { pMax := abs(p6) }
        if abs(p7) > pMax { pMax := abs(p7) }
        if abs(p8) > pMax { pMax := abs(p8) }
        if abs(p9) > pMax { pMax := abs(p9) }
        if abs(p10) > pMax { pMax := abs(p10) }
        if abs(p11) > pMax { pMax := abs(p11) }
        if abs(p12) > pMax { pMax := abs(p12) }
        if abs(p13) > pMax { pMax := abs(p13) }
        if abs(p14) > pMax { pMax := abs(p14) }
        if abs(p15) > pMax { pMax := abs(p15) }
        if abs(p16) > pMax { pMax := abs(p16) }
        if abs(p17) > pMax { pMax := abs(p17) }
        if abs(p18) > pMax { pMax := abs(p18) }
        if abs(p19) > pMax { pMax := abs(p19) }
        if pMax < 0.000000001 { pMax := 0.000000001 }
        q0 = p0 / pMax
        q1 = p1 / pMax
        q2 = p2 / pMax
        q3 = p3 / pMax
        q4 = p4 / pMax
        q5 = p5 / pMax
        q6 = p6 / pMax
        q7 = p7 / pMax
        q8 = p8 / pMax
        q9 = p9 / pMax
        q10 = p10 / pMax
        q11 = p11 / pMax
        q12 = p12 / pMax
        q13 = p13 / pMax
        q14 = p14 / pMax
        q15 = p15 / pMax
        q16 = p16 / pMax
        q17 = p17 / pMax
        q18 = p18 / pMax
        q19 = p19 / pMax
        pastArr = [q0, q1, q2, q3, q4, q5, q6, q7, q8, q9, q10, q11, q12, q13, q14, q15, q16, q17, q18, q19]
        ss = 0.0
        ii = 0
        while ii < 20 {
            d = curArr[ii] - pastArr[ii]
            ss := ss + d * d
            ii := ii + 1
        }
        dist = sqrt(ss)
        lbl = 0 - 1
        if closeHist[j + 1] > closeHist[j] { lbl := 1 }
        insertIdx = 0 - 1
        mm = 0
        while mm < 7 {
            if dist < bestArr[mm] {
                insertIdx := mm
                mm := 7
            }
            mm := mm + 1
        }
        if insertIdx >= 0 {
            mm = 6
            while mm > insertIdx {
                bestArr[mm] := bestArr[mm - 1]
                labArr[mm] := labArr[mm - 1]
                mm := mm - 1
            }
            bestArr[insertIdx] := dist
            labArr[insertIdx] := lbl
        }
        j := j + 1
    }

    upCount = 0
    dnCount = 0
    mm = 0
    while mm < 7 {
        if bestArr[mm] < 999999.0 {
            if labArr[mm] == 1 { upCount := upCount + 1 }
            else { dnCount := dnCount + 1 }
        }
        mm := mm + 1
    }
    mVote := (upCount - dnCount) / 7.0
    meanD = (bestArr[0] + bestArr[1] + bestArr[2] + bestArr[3] + bestArr[4] + bestArr[5] + bestArr[6]) / 7.0
    if meanD < 0.000000001 { meanD := 0.000000001 }
    vv = 0.0
    mm = 0
    while mm < 7 {
        dd = bestArr[mm] - meanD
        vv := vv + dd * dd
        mm := mm + 1
    }
    vv := vv / 7.0
    sdD = sqrt(vv)
    sDis := sdD / meanD
}

// ─── Confidence state: crisp only when both channels agree ───
buyCond = warmup and mVote >= crispThresh and sDis <= maxDis
sellCond = warmup and mVote <= 0 - crispThresh and sDis <= maxDis
buySig = buyCond and not buyCond[1]
sellSig = sellCond and not sellCond[1]

// ─── Signal markers ───
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }
if buySig { plotshape_3d(bar_index, low, "Buy", "diamond", "#22cc88", markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "diamond", "#ff4477", markerSize, 1, "separate") }

// ─── 2D channels: pillar height (margin) + footprint (disagreement) ───
plot(mVote, "Vote Margin", "#22cc88", 2, "separate")
plot(sDis, "Disagreement", "#ffd43b", 1, "separate")
hline(0, "#888888", "separate")

// ─── 3D form: tall narrow tower = crisp, short wide slab = contested ───
plot3d(mVote, "Vote Margin Towers", "bars3d", "#22cc88", "separate")
plot3d(sDis, "Disagreement Footprint", "scatter", "#ffd43b", "separate")

rows = input(50, "Rows", 10, 100, 1)
vaPct = input(70, "ValueAreaPct", 50, 90, 1)
sessLen = input(100, "SessionLookback", 20, 200, 5)
extendVA = input(true, "ExtendVAHVAL")
show3d = input(true, "Show3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
if rng <= 0 {
    rng := 1.0
}
rowH = rng / rows

rowVols = array()
r = 0
while r < rows {
    rowLow = ll + r * rowH
    rowHigh = ll + (r + 1) * rowH
    rv = 0.0
    k = 0
    while k < sessLen {
        bHigh = high[k]
        bLow = low[k]
        bVol = volume[k]
        top = bHigh
        if rowHigh < top {
            top := rowHigh
        }
        bot = bLow
        if rowLow > bot {
            bot := rowLow
        }
        ov = top - bot
        if ov > 0 {
            br = bHigh - bLow
            if br <= 0 {
                rv := rv + bVol
            } else {
                rv := rv + bVol * ov / br
            }
        }
        k := k + 1
    }
    array.push(rowVols, rv)
    r := r + 1
}

totalVol = array.sum(rowVols)

pocRow = 0
pocVol = array.get(rowVols, 0)
r = 1
while r < rows {
    v = array.get(rowVols, r)
    if v > pocVol {
        pocVol := v
        pocRow := r
    }
    r := r + 1
}
pocPrice = ll + (pocRow + 0.5) * rowH
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVol / totalVol
}

vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(rowVols, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 {
        rightVal := array.get(rowVols, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        } else {
            if vaHigh < rows - 1 {
                vaHigh := vaHigh + 1
                accum := accum + rightVal
            }
        }
    }
    guard := guard + 1
}
vah = ll + (vaHigh + 1) * rowH
val = ll + vaLow * rowH
vaWidth = vah - val
insideVA = close >= val and close <= vah
wasInside = close[1] >= val[1] and close[1] <= vah[1]

buySig = close > vah and close[1] <= vah[1] and close[1] >= val[1]
sellSig = close < val and close[1] >= val[1] and close[1] <= vah[1]

terrainSrc = pocPrice + pocShare * rng * 0.25 + (close - pocPrice) * 0.05

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig and show3d {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d")
}
if sellSig and show3d {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}

var lastPocRow = -1.0
if pocRow != lastPocRow and show3d {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 0, "3d")
}
lastPocRow := pocRow

box.new(bar_index - sessLen + 1, vah, bar_index, val, "#4488ff", "rgba(68,136,255,0.12)", 1, "VAZONE")

plot(close, "SignalPrice", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vah, "VAH", "#22cc88", 1, "stepline")
plot(val, "VAL", "#ff4477", 1, "stepline")
plot(pocShare * 100, "POC Share %", "#ffd43b", 1, "separate")
plot(vaWidth, "VA Width", "#4488ff", 1, "separate")

plot3d(terrainSrc, "Value Terrain", "surface", "#4488ff", "3d", 3)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 0)
plot3d(vah, "VAH Rail", "line3d", "#22cc88", "3d", 1)

// Fix 1: var lvl = highest(high, 20) froze the level at bar 0 — changed to plain assignment so it recomputes every bar.
// Fix 2: close[-1] peeked one bar into the future (repaint/lookahead) — changed to close so breakout uses current confirmed close.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) used Pine constants/signature — changed to OakScript (bar_index, price, title, style-string, hex-color).
// Fix 4: plot3d(r, "RSI", "surface", "#b48cff", "3d") forced an oscillator into pane="3d" price scene — changed to pane="separate" per PANE LAW.
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowSrc = input(close, "Flow PSI Source")
critical_threshold = input(150, "Critical Threshold", 50, 300, 1)
spin_factor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
ring_count = input(5, "Ring Count", 1, 10, 1)
ring_expansion_rate = input(2.0, "Ring Expansion", 0.5, 10.0, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = flowSrc
spin_velocity = flow_psi * spin_factor
locked = flow_psi > critical_threshold
maxR = ring_count * 4.0
perimR = 2.0

var discAng = 0.0
var r1 = 0.0
var r2 = 0.0
var r3 = 0.0
var r4 = 0.0
var r5 = 0.0

if locked {
  discAng := discAng[1]
} else {
  discAng := discAng[1] + spin_velocity
}

if locked {
  tmp1 = r1[1] + ring_expansion_rate * 1.0
  if tmp1 > maxR {
    r1 := perimR
  } else {
    r1 := tmp1
  }
  tmp2 = r2[1] + ring_expansion_rate * 2.0
  if tmp2 > maxR {
    r2 := perimR
  } else {
    r2 := tmp2
  }
  tmp3 = r3[1] + ring_expansion_rate * 3.0
  if tmp3 > maxR {
    r3 := perimR
  } else {
    r3 := tmp3
  }
  tmp4 = r4[1] + ring_expansion_rate * 4.0
  if tmp4 > maxR {
    r4 := perimR
  } else {
    r4 := tmp4
  }
  tmp5 = r5[1] + ring_expansion_rate * 5.0
  if tmp5 > maxR {
    r5 := perimR
  } else {
    r5 := tmp5
  }
} else {
  r1 := 0.0
  r2 := 0.0
  r3 := 0.0
  r4 := 0.0
  r5 := 0.0
}

shockFront = (r1 + r2 + r3 + r4 + r5) / 5.0 + flow_psi * 0.01
discWrapped = discAng - 360.0 * (discAng / 360.0 - 0.5)

overTrig = locked and not locked[1]
clearTrig = not locked and locked[1]

if overTrig {
  plotshape(bar_index, high, "Overpressure", "triangledown", "#ff4477")
}

if clearTrig {
  plotshape(bar_index, low, "Clear", "triangleup", "#22cc88")
}

if overTrig {
  plotshape_3d(bar_index, high, "Overpressure", "sphere", "#ff4477", markerSize, 0, "separate", discWrapped, 0, 0)
  label3d(bar_index, high, "OVERPRESSURE", "#ff4477", 1, 1, "separate")
}

plot(flow_psi, "Flow PSI", "#38bdf8", 2, "separate")
plot(spin_velocity, "Spin Velocity", "#a78bfa", 1, "separate")
hline(critical_threshold, "#ff4477", "separate")
plot3d(flow_psi, "Flow Pressure", "trail", "#38bdf8", "separate")
plot3d(shockFront, "Shockwave Front", "torus", "#ff4477", "separate", 1)
